const deck = {
  code: "WB-06",
  category: "workbuddy",
  fileTitle: "WorkBuddy知识库",
  deck: "WorkBuddy 知识库：让 AI 读你的资料再回答",
  slides: [
    { layout: "cover", kicker: "Vibe Coding 学习系列 · WB-06", title: "WorkBuddy 知识库：让 AI 读你的资料再回答", subtitle: "把一批资料喂给 AI，回答有依据、可追溯" },
    { layout: "section", title: "知识库是什么", subtitle: "一次导入一批资料，AI 回答时去库里找依据" },
    { layout: "bullets", title: "知识库和连接器的区别", bullets: [
      "连接器像打电话，实时去某个软件拉最新数据",
      "知识库像档案柜，把一摞文档一次性放进去",
      "连接器适合邮件、会议等实时信息",
      "知识库适合员工手册、产品手册等静态资料",
      "要最新动态用连接器，要基于资料回答用知识库"
    ], notes: "两者都让 AI 读你的数据，但一个实时拉，一个提前喂。" },
    { layout: "section", title: "第一步：建第一个知识库", subtitle: "15 分钟从新建到第一次提问" },
    { layout: "steps", title: "建库四步走", steps: [
      { title: "找到入口", desc: "主界面左侧栏找知识库或我的资料入口，与专家、技能、连接器并列" },
      { title: "新建知识库", desc: "填名称和描述，选择私人或共享的可见范围，点创建" },
      { title: "导入资料", desc: "支持 PDF、Word、Markdown、Excel、CSV、PPT 和网页链接，第一次先导 5-10 份" },
      { title: "等待索引", desc: "5 份小资料约 1-3 分钟，状态变成可用就能提问" }
    ], notes: "第一次选不同类型的非敏感资料：一份 PDF、一份 Word、一份表格。" },
    { layout: "bullets", title: "第一次提问怎么写", bullets: [
      "开头写明基于我的个人工作资料库回答",
      "请 AI 引用资料里的具体段落或数据作依据",
      "要求资料里没有就直接说没找到",
      "回答里的引用段落可以点开核对",
      "核心价值是让回答有依据、可追溯"
    ], notes: "普通 AI 凭训练记忆答，知识库凭你的资料答。" },
    { layout: "cards", title: "建库卡住了怎么办", cards: [
      { title: "导入失败", desc: "检查 PDF 是否加密、Word 是否受保护，文件别太大，文件名别用特殊字符" },
      { title: "索引特别慢", desc: "资料太多太大或网络慢，先建 3-5 份的小库，跑顺后再加" },
      { title: "检索不到内容", desc: "扫描版 PDF 要 OCR，提问别太空泛，先确认资料导入成功" },
      { title: "回答凭记忆", desc: "提问里明确基于某个知识库，并确认该库处于已启用状态" }
    ] },
    { layout: "section", title: "第二步：知识库的进阶管理", subtitle: "分场景建库、更新资料、管好权限" },
    { layout: "bullets", title: "分场景建库与资料更新", bullets: [
      "按场景分库：工作、公司制度、产品、客户、学习笔记",
      "检索时指定某个库，AI 找得更准更快",
      "库太多管理成本高，按需建",
      "偶尔变的资料手动删旧传新",
      "频繁变的资料用连接器自动同步"
    ], notes: "别把所有资料塞进一个库。" },
    { layout: "table", title: "三种知识库的权限", headers: ["类型", "谁能用", "注意"], rows: [
      ["私人知识库", "只有你能用", "个人隐私资料放这里"],
      ["共享知识库", "团队成员都能用", "导入前确认没有敏感信息"],
      ["涉密知识库", "单独建、单独管", "别跟普通库混在一起"]
    ], notes: "共享知识库要谨慎，你导入的资料团队成员都能看到。" },
    { layout: "bullets", title: "黄金提问模板", bullets: [
      "开头写明基于某个知识库回答",
      "问题要具体，别问说说我们公司这种空泛问题",
      "要求引用具体段落或数据作为依据",
      "多份资料冲突时，让 AI 列出来自己判断",
      "明确告诉 AI 找不到就说没找到，不要硬编"
    ], notes: "五原则：指定库、问具体事、要依据、容许不知道、跨库分开问。" },
    { layout: "cards", title: "四种实战场景", cards: [
      { title: "产品专家", desc: "导入产品手册、功能说明和 FAQ，准确回答客户的功能问题" },
      { title: "合规顾问", desc: "导入员工手册、报销规范，给出公司真实政策而不是通用模板" },
      { title: "项目助理", desc: "导入过往方案、合同和复盘，几秒列出项目清单去见客户" },
      { title: "学习辅导", desc: "导入课程笔记和读书心得，把零散学习串成体系" }
    ] },
    { layout: "bullets", title: "知识库的边界和坑", bullets: [
      "实时股价、新闻、库存改用连接器",
      "跨多个库的复杂推理容易乱，分库分别问更准",
      "扫描版 PDF 要先做 OCR，再转成可复制文字导入",
      "资料冲突会让 AI 选不准，定期清理过期文档",
      "机密和隐私资料别导入，也别混进共享库"
    ], notes: "知识库主要处理文字，图片视频和精确计算都比较弱。" },
    { layout: "end", title: "让 AI 回答有依据、可追溯", subtitle: "先建小库跑通，再慢慢扩容" }
  ]
};

const content = JSON.stringify(deck, null, 2);
const w = await tools.write({ file_path: 'vibe-coding-ppt/tutorials-content/wb-06.json', content });

// validate
const violations: string[] = [];
const slides: any[] = deck.slides;
if (slides.length < 10 || slides.length > 14) violations.push('slide count ' + slides.length);
slides.forEach((s, i) => {
  const loc = `slide ${i + 1} (${s.layout})`;
  if (s.layout === 'bullets') {
    if (s.bullets.length > 5) violations.push(`${loc} bullets ${s.bullets.length}`);
    s.bullets.forEach((b: string) => { if ([...b].length > 42) violations.push(`${loc} too long(${[...b].length}): ${b}`); });
  }
  if (s.layout === 'cards' && (s.cards.length < 3 || s.cards.length > 4)) violations.push(`${loc} cards ${s.cards.length}`);
  if (s.layout === 'steps' && (s.steps.length < 3 || s.steps.length > 4)) violations.push(`${loc} steps ${s.steps.length}`);
  if (s.layout === 'table') {
    if (s.headers.length > 5) violations.push(`${loc} cols ${s.headers.length}`);
    if (s.rows.length > 6) violations.push(`${loc} rows ${s.rows.length}`);
  }
});
if (slides[0].layout !== 'cover' || slides[0].kicker !== 'Vibe Coding 学习系列 · WB-06') violations.push('cover/kicker');
const allowed = ['cover','section','bullets','cards','table','steps','quote','end'];
slides.forEach((s, i) => { if (!allowed.includes(s.layout)) violations.push(`slide ${i+1} layout ${s.layout}`); });

return JSON.stringify({ written: w.path, operation: w.operation, slides: slides.length, violations }, null, 2);
", "description": "Write and validate WB-06 JSON"}

