  try { d = JSON.parse(raw); } catch (e: any) { problems.push(`${c}: JSON 解析失败 ${e.message}`); continue; }
  const expectedKicker = `Vibe Coding 学习系列 · ${c.toUpperCase()}`;
  const issues: string[] = [];
  if (!['code','category','fileTitle','deck','slides'].every(k => k in d)) issues.push('顶层字段缺失');
  if (d.code !== c.toUpperCase()) issues.push(`code 字段 ${d.code}`);
  if (d.category !== 'workbuddy') issues.push('category');
  const slides = d.slides;
  if (!(slides.length >= 10 && slides.length <= 14)) issues.push(`张数 ${slides.length}`);
  if (slides[0].layout !== 'cover' || slides[0].kicker !== expectedKicker) issues.push('封面/kicker');
  slides.forEach((s: any, i: number) => {
    const loc = `#${i+1}(`) + s.layout + ')';
    if (!allowed.includes(s.layout)) issues.push(`${loc} 非法 layout`);
    if (!s.title) issues.push(`${loc} 缺 title`);
    if (s.layout === 'bullets') {
      if (s.bullets.length > 5) issues.push(`${loc} bullets=${s.bullets.length}`);
      s.bullets.forEach((b: string) => { if ([...b].length > 42) issues.push(`${loc} 超长(${[...b].length}): ${b}`); });
    }
    if (s.layout === 'cards') { if (s.cards.length < 3 || s.cards.length > 4) issues.push(`${loc} cards=${s.cards.length}`); s.cards.forEach((x:any)=>{ if(!x.title||!x.desc) issues.push(`${loc} card 字段缺失`);}); }
    if (s.layout === 'steps') { if (s.steps.length < 3 || s.steps.length > 4) issues.push(`${loc} steps=${s.steps.length}`); s.steps.forEach((x:any)=>{ if(!x.title||!x.desc) issues.push(`${loc} step 字段缺失`);}); }
    if (s.layout === 'table') { if (s.headers.length > 5) issues.push(`${loc} 列=${s.headers.length}`); if (s.rows.length > 6) issues.push(`${loc} 行=${s.rows.length}`); }
  });
  if (issues.length) problems.push(`${c}: ${issues.join('; ')}`);
  report.push({ code: d.code, file: p, deck: d.deck, slides: slides.length, bytes: Buffer.byteLength(raw), ok: issues.length === 0 });
}

return JSON.stringify({ report, problems }, null, 2);
